+	case BF_PANEL_OUT_CH12:		return 1;
+	case BF_PANEL_OUT_PHONES:	return 2;
+	case BF_PANEL_OUT_OPT:		return 3;
+	case 0x01:			return 1;	/* base-mode Ch 1/2 */
+	case 0x02:			return 2;	/* base-mode Phones */
+	default:			return 0;
